// Gemini ka JSON parse karke har scene alag item banao
const raw = $input.first().json.candidates[0].content.parts[0].text;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleaned);

if (!Array.isArray(parsed.scenes) || parsed.scenes.length === 0) {
  throw new Error('Gemini ne scenes nahi diye — workflow dobara run karo');
}

const meta = {
  title: parsed.title,
  description: parsed.description,
  tags: parsed.tags,
};

return parsed.scenes.map((s, i) => ({
  json: {
    scene_index: i + 1,
    hook: s.hook,
    voiceover: s.voiceover,
    veo_prompt: s.veo_prompt,
    pexels_query: s.pexels_query,
    meta,
  },
}));

// Har poll cycle par Veo operation names FRESH items ke roop me do
// (loop-back par input me .name nahi hota, isliye hamesha submit node se lo)
return $('4. Veo (Submit Scenes)').all()
  .filter((i) => i.json && i.json.name)
  .map((i) => ({ json: { name: i.json.name } }));

// Veo results collect karo — fail hone wale scenes Pexels fallback me jayenge
const ops = $input.all();
const sceneItems = $('Split Scenes').all();
const sceneCount = sceneItems.length;

if (ops.length !== sceneCount) {
  throw new Error('Veo status items (' + ops.length + ') scenes (' + sceneCount + ') se match nahi kar rahe');
}

const pending = ops.filter((o) => !o.json.done).length;
if (pending > 0) {
  return [{ json: { all_done: 'false', pending } }];
}

let failMsg = '';
const failed = ops.find((o) => o.json.error);
if (failed) {
  failMsg = (failed.json.error && failed.json.error.message) || 'unknown Veo error';
}

const scenes = sceneItems.map((s, i) => {
  const resp = ops[i].json.response || {};
  const samples = (resp.generateVideoResponse || {}).generatedSamples || [];
  return {
    scene_index: s.json.scene_index,
    hook: s.json.hook,
    voiceover: s.json.voiceover,
    pexels_query: s.json.pexels_query,
    video_uri: samples[0] && samples[0].video ? samples[0].video.uri : null,
  };
});

const okCount = scenes.filter((s) => s.video_uri).length;
if (okCount === 0) {
  throw new Error('Veo se ek bhi clip nahi bana' + (failMsg ? ' — ' + failMsg : '') + '. Billing check karo ya topic thoda change karke rerun karo.');
}

return [{ json: { all_done: 'true', scenes, veo_ok: okCount, veo_fallback: scenes.length - okCount } }];

// Jin scenes ke Veo clips ban gaye, sirf wahi download ke liye nikalo
return $('Veo Collector').first().json.scenes
  .filter((s) => s.video_uri)
  .map((s) => ({ json: s }));

// Veo clips + Pexels fallback merge karke final scene list banao
const collected = $('Veo Collector').first().json.scenes;
const hosted = $('6. Host Veo Clip (tmpfiles.org)').all();
const pexelsItems = $('3. Pexels (Fallback Footage)').all();
const first = $('Split Scenes').first().json;

const dl = (u) => u.replace('tmpfiles.org/', 'tmpfiles.org/dl/');

function pickFile(videos) {
  if (!videos || !Array.isArray(videos.videos) || videos.videos.length === 0) return null;
  for (const v of videos.videos) {
    const files = (v.video_files || [])
      .filter((f) => f.link)
      .sort((a, b) => (b.height || 0) - (a.height || 0));
    const portrait = files.find((f) => f.height > f.width && f.height >= 1280);
    if (portrait) return portrait.link;
  }
  const v0 = videos.videos[0];
  const f0 = v0.video_files && v0.video_files[0];
  return f0 ? f0.link : null;
}

let ptr = 0;
const scenes = collected.map((s) => {
  let clip_url = null;
  let source = 'pexels';
  if (s.video_uri && hosted[ptr]) {
    clip_url = dl(hosted[ptr].json.data.url);
    ptr++;
    source = 'veo';
  } else {
    clip_url = pickFile(pexelsItems[s.scene_index - 1] ? pexelsItems[s.scene_index - 1].json : null);
  }
  return {
    scene_index: s.scene_index,
    hook: s.hook,
    voiceover: s.voiceover,
    clip_url,
    source,
  };
});

return [{
  json: {
    meta: first.meta,
    scenes,
    veo_ok: collected.filter((s) => s.video_uri).length,
    pexels_fallback: scenes.filter((s) => s.source === 'pexels').length,
  },
}];

// Final movie: Veo/Pexels footage + free Hindi voice + boxed captions + hooks + branded outro
const assets = $('Assets Ready').first().json;
const cfg = $('1. Config and API Keys').first().json;
const pexelsItems = $('3. Pexels (Fallback Footage)').all();
const voice = cfg.VOICE || 'hi-IN-MadhurNeural';
const subLang = (cfg.LANGUAGE || 'Hindi').toLowerCase().includes('eng') ? 'en' : 'hi';

function pickFile(videos) {
  if (!videos || !Array.isArray(videos.videos) || videos.videos.length === 0) return null;
  for (const v of videos.videos) {
    const files = (v.video_files || [])
      .filter((f) => f.link)
      .sort((a, b) => (b.height || 0) - (a.height || 0));
    const portrait = files.find((f) => f.height > f.width && f.height >= 1280);
    if (portrait) return portrait.link;
  }
  return null;
}

const scenes = assets.scenes.map((s, i) => {
  const elements = [];
  // Background footage — Veo clip ya Pexels fallback (mute, voiceover clean)
  if (s.clip_url) elements.push({ type: 'video', src: s.clip_url, volume: 0 });
  // Free neural Hindi voiceover — scene duration voice se auto-fit hoti hai
  elements.push({ type: 'voice', text: s.voiceover, voice });
  // Auto-synced boxed captions (voice ke saath)
  elements.push({
    type: 'subtitles',
    language: subLang,
    settings: {
      style: 'boxed-word',
      'font-family': 'Inter',
      'font-size': 64,
      'word-color': '#FFFFFF',
      'line-color': '#FFFFFF',
      'outline-color': '#000000',
      'box-color': '#000000',
      position: 'bottom-center',
    },
  });
  // Golden hook title (upar)
  elements.push({ type: 'text', text: s.hook, position: 'top-center', 'font-size': 60, color: '#FFD700' });

  const scene = { comment: 'Scene ' + (i + 1) + ' (' + s.source + ')', elements };
  if (i > 0) scene.transition = { style: 'fade', duration: 0.5 };
  return scene;
});

// Branded outro — FOLLOW CTA (Pexels footage background)
const outroClip = pickFile(pexelsItems[0] ? pexelsItems[0].json : null);
const outroElements = [];
if (outroClip) outroElements.push({ type: 'video', src: outroClip, volume: 0 });
outroElements.push({ type: 'text', text: 'FOLLOW ' + (cfg.CHANNEL_TAG || ''), position: 'center', 'font-size': 84, color: '#FFFFFF' });
outroElements.push({ type: 'text', text: 'LIKE • SHARE • SUBSCRIBE', position: 'bottom-center', 'font-size': 44, color: '#FFD700' });
scenes.push({ comment: 'Outro', duration: 3, elements: outroElements, transition: { style: 'fade', duration: 0.5 } });

const movie = {
  comment: 'AI Short — Veo footage + free stack (Gemini Pro + JSON2Video)',
  resolution: 'instagram-story',
  quality: 'high',
  scenes,
};

return [{ json: { movie, meta: assets.meta, veo_ok: assets.veo_ok, pexels_fallback: assets.pexels_fallback } }];

// Render result validate karo — error ho to clear message do
const status = $input.first().json.movie || {};
if (status.status === 'error') {
  throw new Error('Render fail hua: ' + (status.message || 'unknown JSON2Video error'));
}
if (!status.url) {
  throw new Error('Render URL nahi mila — JSON2Video quota/plan check karo');
}
return [{ json: { url: status.url } }];
